{
  "name": "ble_schedule_conn_event",
  "confidence": "medium",
  "docstring": "Updates a BLE connection environment timestamp, arms its kernel event timer, and marks the corresponding connection slot and event bitmap as active.",
  "subsystem": "ble",
  "var_renames": {
    "a1": "conn_env",
    "v1": "event_timing_offset",
    "v3": "base_event_time",
    "v4": "updated_timestamp",
    "v5": "conn_idx",
    "v6": "global_event_state",
    "v7": "conn_event_slot",
    "v8": "conn_env_flags",
    "v10": "conn_env_state"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "u16 connection environment flags; bit 0x0008 is set to mark the connection/event active"
    },
    {
      "offset": 4,
      "meaning": "u8 connection state; zero causes the connection index bit to be set in the global event bitmap"
    },
    {
      "offset": 12,
      "meaning": "u32 timing offset added when calculating the event time"
    },
    {
      "offset": 16,
      "meaning": "u32 timestamp increment added to the 64-bit timestamp at offset 24"
    },
    {
      "offset": 24,
      "meaning": "u64 accumulated connection timestamp"
    },
    {
      "offset": 47,
      "meaning": "u8 connection/event index used for per-connection slot lookup and event bit position"
    },
    {
      "offset": 52,
      "meaning": "kernel event or lock object for this connection environment"
    },
    {
      "offset": 56,
      "meaning": "u32 timestamp snapshot copied from a global timer or base value"
    }
  ]
}
